def hex_key(num):
    """Counts the number of hexadecimal digits that are prime numbers."""
    # Set of prime hexadecimal digits (2, 3, 5, 7, B, D)
    prime_hex_digits = {'2', '3', '5', '7', 'B', 'D'}
    count = 0
    for ch in num:
        if ch in prime_hex_digits:
            count += 1
    return count
